<script setup lang="ts">
import { useRequestForm } from '../../composables/useRequestForm'
import type { CatalogVo } from '../../api/account'
import type { RequestDetail } from '../../api/repair-request'
import type { BusinessReceipt } from '../../api/common'
import ImagePicker from '../../components/attachment/ImagePicker.vue'
import ProtectedImage from '../../components/attachment/ProtectedImage.vue'
import { onBeforeRouteLeave } from 'vue-router'
import { shallowRef } from 'vue'
import { useBusinessConfirmation } from '../../composables/useBusinessConfirmation'
import InlineConfirmation from '../../components/common/InlineConfirmation.vue'
const props = defineProps<{ initialLocationId?: string; detail?: RequestDetail; catalog?: CatalogVo }>(), emit = defineEmits<{ saved: [receipt: BusinessReceipt] }>()
const confirmation = useBusinessConfirmation(), saved = shallowRef(false)
const { catalog, draft, buildingId, floorId, locationId, message, busy, directoryLoading, floors, locations, legacy, canSubmit, context, historicalAttachments, chooseLocation, chooseBuilding, chooseFloor, loadDirectory, submit, checkPending, retryPending, acceptCurrentVersion, discard } = useRequestForm(props, receipt => { saved.value = true; emit('saved', receipt) }, confirmation.ask)
const selected = (event: Event) => (event.target as HTMLSelectElement).value
onBeforeRouteLeave(() => saved.value || !props.detail || !draft.value || confirmation.ask('补充内容尚未提交。离开后仅在同次登录内保留这份草稿，是否离开？'))
</script>
<template><InlineConfirmation :message="confirmation.message.value" @answer="confirmation.answer" /><section class="request-form"><h2>{{ detail ? '补充原申请' : '新建报修' }}</h2><p class="muted">按损坏物品所在房间／楼层区域报修，名称与描述由你填写。联系人只保存为本次申请的联系信息。</p><p v-if="detail" class="notice">请对照退回意见修改原申请，编号和首次提交时间保留。</p><p v-if="message" class="notice" role="alert">{{ message }}</p><p v-if="directoryLoading" role="status">正在读取可报修位置…</p><button v-if="!catalog && !directoryLoading" class="secondary" type="button" @click="loadDirectory">重试位置目录</button>
  <div v-if="catalog && !legacy" class="position-fields"><label>楼栋<select :value="buildingId" :disabled="!!busy" @change="chooseBuilding(selected($event))"><option v-for="b in catalog.buildings" :key="b.id" :value="b.id">{{ b.name }}</option></select></label><label>楼层<select :value="floorId" :disabled="!!busy" @change="chooseFloor(selected($event))"><option v-for="f in floors" :key="f.id" :value="f.id">{{ f.name }}</option></select></label><label>报修房间／区域<select :value="locationId" :disabled="!!busy" @change="chooseLocation(selected($event))"><option value="">请选择可报修位置</option><option v-for="l in locations" :key="l.id" :value="l.id" :disabled="!l.canCreateRequest">{{ l.name }}{{ l.reportable ? '' : ' · 仅供观察' }}</option></select></label></div>
  <p v-if="legacy" class="notice">旧文字申请：保持未关联3D位置，按原地址补充。</p><p v-if="!draft && catalog" class="muted">先选择可报修位置；不同位置各自保留一份同次登录草稿。</p>
  <form v-if="draft" @submit.prevent="submit"><fieldset class="form-fields" :disabled="!!busy || !!draft.pending || !canSubmit"><label>设备名称<input v-model="draft.equipmentName" required maxlength="100" autocomplete="off"></label><label>设备类别（可选自由文本）<input v-model="draft.equipmentCategory" maxlength="100" autocomplete="off"></label><label>详细地址（保留你的原文）<input v-model="draft.addressText" required maxlength="500" autocomplete="off"></label><label>故障描述<textarea v-model="draft.description" required maxlength="4000" rows="5"></textarea></label><div class="form-grid"><label>本次联系人<input v-model="draft.contactName" required maxlength="100" autocomplete="off"></label><label>本次联系电话<input v-model="draft.contactPhone" required pattern="1[3-9][0-9]{9}" maxlength="11" inputmode="tel" autocomplete="off"></label></div><ImagePicker v-model="draft.images" :context="context" :disabled="!!busy || !!draft.pending || !canSubmit" /></fieldset>
    <p v-if="detail && draft.version !== detail.version" class="notice">原申请版本已变化，编辑内容保留。请核对状态和意见后再提交。 <button type="button" class="text-button" :disabled="!!draft.pending || !!busy" @click="acceptCurrentVersion">核对并采用当前版本</button></p>
    <div v-if="draft.pending" class="notice" role="status"><strong>提交结果待确认</strong><p>保留原输入和提交标识。尚未确认不等于提交失败，不能修改后换标识重发。</p><div class="actions"><button type="button" class="secondary" :disabled="!!busy" @click="checkPending">核对原操作结果</button><button type="button" class="secondary" :disabled="!!busy" @click="retryPending">使用原标识重试</button></div></div>
    <div class="actions"><button type="submit" class="primary" :disabled="!!busy || !!draft.pending || !canSubmit">{{ busy ? `${busy}…` : detail ? '上传新增图片并重提原申请' : '上传图片并提交申请' }}</button><button type="button" class="secondary" :disabled="!!busy || !!draft.pending" @click="discard">放弃这份草稿</button></div>
  </form><section v-if="historicalAttachments.length" class="history-photos"><h3>历史已提交图片（保留，不可移除）</h3><ProtectedImage v-for="image in historicalAttachments" :key="image.id" :attachment="image" /></section></section></template>
<style scoped>.request-form { min-width: 0; }.position-fields { display: grid; grid-template-columns: 1fr 1fr 1.3fr; gap: 14px; margin: 22px 0; }.form-fields { min-width: 0; border: 0; padding: 0; margin: 0; display: grid; gap: 18px; }.history-photos { border-top: 1px solid #dce6ea; margin-top: 26px; padding-top: 20px; }@media(max-width:767px) { .position-fields { grid-template-columns: 1fr; } }</style>
